-- Reversible integration test. Premium only. Fixtures and profile changes roll back.
begin;
set local request.jwt.claim.sub='3aab5422-54c8-4ebe-adc7-1d6c1a26684e';
set local request.jwt.claim.role='authenticated';
update public.user_profiles set must_change_password=false where user_id=auth.uid();
create temporary table premium_test_results(test text,result text) on commit drop;
do $$
declare c uuid; wh uuid; p uuid; v uuid; cust1 uuid; cust2 uuid; oid1 uuid; oid2 uuid; oid3 uuid; b uuid; r jsonb; x record; a jsonb; allocations jsonb:='[]'; movement_count integer; stock_before numeric; rejected boolean; role_name text;
begin
 select company_id into c from public.user_profiles where user_id=auth.uid();
 insert into warehouses(company_id,code,name)values(c,'UAT-WH','คลังทดสอบ')returning id into wh;
 insert into products(company_id,code,name,base_uom)values(c,'UAT-P','สินค้าทดสอบ','KG')returning id into p;
 insert into vehicles(company_id,code,plate_no)values(c,'UAT-V','ทดสอบ-01')returning id into v;
 insert into customers(company_id,code,name)values(c,'UAT-C1','ลูกค้าทดสอบ 1')returning id into cust1;
 insert into customers(company_id,code,name)values(c,'UAT-C2','ลูกค้าทดสอบ 2')returning id into cust2;
 insert into monthly_product_costs(company_id,product_id,cost_month,unit_cost)values(c,p,date_trunc('month',current_date)::date,20);
 perform post_goods_receipt(wh,null,'UAT-GR',current_date,jsonb_build_array(jsonb_build_object('product_id',p,'qty',100,'unit_cost',20)),'PREMIUM-UAT-GR');
 r:=create_order(cust1,current_date,now()+interval '2 days',jsonb_build_array(jsonb_build_object('product_id',p,'warehouse_id',wh,'qty',10,'unit_price',50)),'PUAT-1');oid1:=(r->>'id')::uuid;
 r:=create_order(cust2,current_date,now()+interval '2 days',jsonb_build_array(jsonb_build_object('product_id',p,'warehouse_id',wh,'qty',20,'unit_price',50)),'PUAT-2');oid2:=(r->>'id')::uuid;
 r:=create_order(cust1,current_date,now()+interval '2 days',jsonb_build_array(jsonb_build_object('product_id',p,'warehouse_id',wh,'qty',5,'unit_price',50)),'PUAT-3');oid3:=(r->>'id')::uuid;
 update user_profiles set app_role='SALES' where user_id=auth.uid();
 r:=premium_request_vehicle_booking(v,now()+interval '2 days',now()+interval '2 days 2 hours',array[oid1,oid2],'UAT');b:=(r->>'id')::uuid;
 insert into premium_test_results values('Sales: multi customer / Order request','PASS');
 rejected:=false;begin perform premium_decide_vehicle_booking(b,'REVISION_REQUESTED','กรุณาปรับเวลา');
 update user_profiles set app_role='SALES' where user_id=auth.uid();
 perform premium_resubmit_vehicle_booking(b,v,now()+interval '2 days',now()+interval '2 days 2 hours',array[oid1,oid2],'แก้ไขแล้ว');
 if (select status from vehicle_booking_requests where id=b)<>'PENDING' then raise exception 'RESUBMIT_FAILED';end if;
 insert into premium_test_results values('Return for revision and Sales resubmit on same booking','PASS');
 update user_profiles set app_role='LOGISTICS' where user_id=auth.uid();
 perform premium_decide_vehicle_booking(b,'CONFIRMED',null);exception when others then if sqlerrm='ROLE_NOT_ALLOWED' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'SALES_APPROVAL_NOT_BLOCKED';end if;
 insert into premium_test_results values('Sales cannot approve','PASS');
 rejected:=false;begin perform premium_request_vehicle_booking(v,now()+interval '2 days 1 hour',now()+interval '2 days 3 hours',array[oid3],'overlap');exception when others then if sqlerrm='VEHICLE_TIME_CONFLICT' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'OVERLAP_NOT_BLOCKED';end if;
 insert into premium_test_results values('Overlapping booking blocked','PASS');
 perform premium_request_vehicle_booking(v,now()+interval '2 days 2 hours',now()+interval '2 days 4 hours',array[oid3],'next trip');
 insert into premium_test_results values('Same vehicle next trip and adjacent times allowed','PASS');
 update user_profiles set app_role='LOGISTICS' where user_id=auth.uid();
 perform premium_decide_vehicle_booking(b,'REVISION_REQUESTED','กรุณาปรับเวลา');
 update user_profiles set app_role='SALES' where user_id=auth.uid();
 perform premium_resubmit_vehicle_booking(b,v,now()+interval '2 days',now()+interval '2 days 2 hours',array[oid1,oid2],'แก้ไขแล้ว');
 if (select status from vehicle_booking_requests where id=b)<>'PENDING' then raise exception 'RESUBMIT_FAILED';end if;
 insert into premium_test_results values('Return for revision and Sales resubmit on same booking','PASS');
 update user_profiles set app_role='LOGISTICS' where user_id=auth.uid();
 perform premium_decide_vehicle_booking(b,'CONFIRMED',null);
 rejected:=false;begin perform premium_dispatch_booking(b,null);exception when others then if sqlerrm='ORDER_NOT_READY_FOR_DELIVERY' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'UNISSUED_DISPATCH_NOT_BLOCKED';end if;
 update user_profiles set app_role='WAREHOUSE' where user_id=auth.uid();
 for x in select id,order_id,qty from order_lines where order_id in (oid1,oid2) loop perform issue_order(x.order_id,jsonb_build_array(jsonb_build_object('order_line_id',x.id,'qty',x.qty)),'PUAT-ISSUE-'||x.order_id);end loop;
 select on_hand into stock_before from stock_balances where company_id=c and warehouse_id=wh and product_id=p;
 if stock_before<>70 then raise exception 'WRONG_STOCK_AFTER_ISSUE %',stock_before;end if;
 select count(*) into movement_count from stock_movements where company_id=c and product_id=p;
 update user_profiles set app_role='WAREHOUSE_LOGISTICS' where user_id=auth.uid();
 perform premium_dispatch_booking(b,null);perform premium_dispatch_booking(b,null);
 if (select count(*) from delivery_trips where booking_id=b)<>2 then raise exception 'DUPLICATE_DISPATCH';end if;
 insert into premium_test_results values('Logistics / combined role dispatch; warehouse issued once; repeat safe','PASS');
 for x in select id,order_id from delivery_trips where booking_id=b order by order_id loop
  select jsonb_agg(jsonb_build_object('trip_line_id',id,'received_qty',issued_qty,'variance_reason',null))into a from delivery_trip_lines where trip_id=x.id;
  allocations:=allocations||jsonb_build_object('trip_id',x.id,'freight',case when x.order_id=oid1 then 40 else 60 end,'lines',a,'pod_reference','UAT-POD','expenses','[]'::jsonb);
 end loop;
 rejected:=false;begin perform premium_complete_booking(b,101,allocations);exception when others then if sqlerrm='FREIGHT_ALLOCATION_MISMATCH' then rejected:=true;else raise;end if;end;
 if not rejected then raise exception 'ALLOCATION_MISMATCH_NOT_BLOCKED';end if;
 if exists(select 1 from invoices where customer_id in(cust1,cust2))then raise exception 'PARTIAL_INVOICE_COMMIT';end if;
 insert into premium_test_results values('Freight sum mismatch blocks all invoice posting','PASS');
 perform premium_complete_booking(b,100,allocations);perform premium_complete_booking(b,100,allocations);
 if (select sum(revenue) from invoices where customer_id in(cust1,cust2))<>1500 or (select sum(product_cost) from invoices where customer_id in(cust1,cust2))<>600 or (select sum(freight_cost) from invoices where customer_id in(cust1,cust2))<>100 then raise exception 'INVOICE_RECONCILIATION_FAILED';end if;
 if (select count(*) from invoices where customer_id in(cust1,cust2))<>2 then raise exception 'INVOICE_DUPLICATED';end if;
 if (select on_hand from stock_balances where warehouse_id=wh and product_id=p)<>stock_before or (select count(*) from stock_movements where product_id=p)<>movement_count then raise exception 'DOUBLE_STOCK_CUT';end if;
 insert into premium_test_results values('2 customer invoices: sales 1500, cost 600, freight 100, contribution 800; no double stock cut; repeat safe','PASS');
 foreach role_name in array array['WAREHOUSE','OWNER'] loop
  update user_profiles set app_role=role_name where user_id=auth.uid();
  rejected:=false;begin perform premium_dispatch_booking(b,null);exception when others then if sqlerrm='ROLE_NOT_ALLOWED' then rejected:=true;else raise;end if;end;
  if not rejected then raise exception 'ROLE_NOT_BLOCKED %',role_name;end if;
  insert into premium_test_results values(role_name||' cannot dispatch','PASS');
 end loop;
 update user_profiles set app_role='ADMIN' where user_id=auth.uid();
 perform premium_complete_booking(b,100,allocations);
 insert into premium_test_results values('Admin role supported','PASS');
end $$;
select jsonb_agg(to_jsonb(r)) as premium_uat from premium_test_results r;
rollback;
